actions.command:
set -euo pipefail
if command -v nginx >/dev/null 2>&1; then echo NGINX_PRESENT; else echo NGINX_MISSING; fi
if [ ! -f /etc/nginx/nginx.conf ]; then mkdir -p /app/nginx; cat > /app/nginx/nginx.conf <<'EOF'
worker_processes  1;
events { worker_connections  1024; }
http {
  server {
    listen 80;
    location / {
      return 200 'win311 remote access';
      add_header Content-Type text/plain;
    }
  }
}
EOF
fi
if command -v nginx >/dev/null 2>&1; then nginx -c /app/nginx/nginx.conf -p /app/nginx -g 'daemon on;'; else echo 'NO_NGINX_BINARY'; fi
sleep 1
ss -ltnp | grep ':80\b' || true
